from 写入第二遍 import add,load,save
add('23_003',11,'16:9，董白与青并肩的双人中近景，青在画面左侧垂头，董白在右侧，搭肩手臂与扣住前臂的手留全；相机从较低处随扶起抬升，落幅两人的头肩同高。','董白靠到青身边，屈膝俯身把她靠近自己的手臂搭过肩，外侧手扣住那条前臂，内侧臂护住她后腰；她踩稳脚，用腿部撑起把青带到身侧。青的头一直垂着，身体刚直起便把重量交给董白，指尖从轻勾慢慢松开。董白扶稳后抬起下巴，半垂眼得意笑着招她当马仔；说到试用期，笑口向一边挑，扣前臂的手又收紧一回，免得青滑下。','两人头发之间与两侧露蓝灰云天，低处米灰薄尘薄薄飘过，平台地面只在抬升起幅下缘短暂显出。','冷白云光从上方铺开，黑裙、银发和裸露手臂明暗柔和，石面弱补光随抬升渐淡。','董白靠近两下轻鞋声，屈膝起身的衣料绷响，青长发从地面拖起后扫过衣肩。',ja=['うん、あんた結構使えるじゃない…私の子分になりなさい。','もちろん、数か月の試用期間はあるけどね。'],tone='董白扶人同时得意评价，前句像赏识下属；后句故意端起招人的架子，尾音轻轻扬起。',kind='mixed',phase='process',node={'叙事阶段':'董白扶起青，搭肩架稳并招揽','青.状态':'扶起后闭眼，渐渐失去回应','青.支撑':'靠董白一侧手臂搭肩，身体由董白架住','董白.位置':'紧靠青，外侧手扣前臂，内侧臂护腰'},meaning='董白将青扶起为搭肩搀扶，原格垂头、扣前臂与董白得意半垂眼保留。',motion='两人从低位升到并肩，青的重量转交董白，镜头跟升后停稳。',ground='董白双脚分开承重；青双脚回到地面但重心靠同伴，未被横抱。',characters=['青','董白'],card={'opening':'董白拿到让功的承诺，愿意接手照料青。','beats':['俯身搭臂、扣前臂、护后腰，踩稳扶起','青把重量交过来，指尖渐松','董白架稳后得意招揽，补一句试用期并再扣紧'],'coupling':'招揽的从容由真实承重支撑，手上照料与口头端架子并行。','landing':'青已被架在肩旁，董白仍等她答应。'})
add('23_004',3,'16:9，双人脸侧近景，青闭眼侧脸在画面左侧近层，董白在中央偏右，仍留青搭过来的手臂边缘；固定机位，董白目光斜向青。','董白说完还等着回应，眼珠先向青脸上偏，笑口却渐渐停住；青双眼闭合，嘴微张，头随着呼吸轻轻向下点，搭肩的手指完全松了。董白半垂的眼睛又抬起一点，凑近看她，再说出发现睡着的抱怨；话落后手臂仍稳稳托着，肩没有松开。','两张脸与发束之外是蓝灰云层，右侧开一小块浅冷灰天空。','上方冷白柔光照侧脸，银发与黑发分层清楚，嘴旁阴影浅软。','青一口均匀偏轻的呼吸，董白侧头时发丝扫领，承重姿势中的衣料轻绷。',ja=['何よ。寝ちゃったの？'],tone='董白先带没等到答复的不满，后半句意外地确认，末尾轻轻落下。',kind='mixed',phase='reaction',node={'叙事阶段':'董白发现青睡着','青.状态':'闭眼失去回应，被架住','董白.位置':'继续搭肩搀扶青'},meaning='青闭眼微张口、董白半垂眼斜看与原句保留，睡着发生在搀扶之后。',characters=['青','董白'],card={'opening':'董白还以为会听到招揽的答复。','beats':['等一下，眼珠偏去，笑口停','凑近确认闭眼呼吸，出声抱怨'],'coupling':'嘴上不满，肩与托臂保持支撑。','landing':'她已确认青不回应，仍将青扶稳。'})
d=load();p=next(p for p in d['panels'] if p['image']=='第28話_24_001.jpg');p['composition_correction_history']=p['first_pass']['observation'];p['first_pass']['observation']='狭长环境空镜，下方密细林冠，云雾压在上方；画面中央朝阳升起的亮光穿透云雾，形成上升的浅亮射束与几何光面。没有悬空岩台实体。小鸟鸣拟声位于左中，无气泡。';save(d)
add('24_001',3.5,'16:9，林海与晨光的远景空镜，林冠从画面左下斜铺向中央，朝阳升起的光线位于中央云雾交界；镜头从林冠上摇到穿云光束，落幅以中央亮带和两侧分层云雾为主。','林海上缘中央的浅金白光带缓缓升亮，薄雾先透出几条细束，随后光束连成更宽的柔亮面；云雾沿亮面两侧缓慢漂开，林冠顶缘渐渐多出一点暖色。画面中央明亮射束向上伸展，远处两声短鸟鸣从林海里传来，人物始终在画外。','深浅灰绿林冠、低处米灰晨雾与上方蓝灰云层；中央浅金白晨光穿过云雾，几何亮面均为透光层次。','中央低处升起的朝阳提供浅金白透雾光，周围仍保留冷灰云影；晨光由弱到强，林海顶缘获柔暖亮边。','两声短鸟鸣，林海远风与薄雾间空旷底声。',kind='state',phase='state',node={'叙事阶段':'朝阳升起，光线转暖变亮','场景光线':'中央朝阳穿雾，冷灰云光与浅金白晨光并存'},meaning='用户纠正：24_001中间是朝阳升起光线，光束与林海构成空镜，不建悬空岩台。',characters=[])
